//! test_lufs_golden_vectors.rs — the Rust lane of the C8 three-way LUFS
//! pin (WS-C / AHEAD C8).
//!
//! C8 designated `streamify-audio/src/lufs.rs` the canonical BS.1770-4
//! implementation and pinned the C++ twin (`native/dsp/LufsNormalizer.cc`)
//! to its golden vectors. This test is the RUST side of that pin: it
//! regenerates every fixture signal, measures it through the REAL
//! canonical [`LufsAnalyzer`], and asserts the result matches the shared
//! checked-in fixture (`tests/lufs_golden_vectors_data.rs`, generated by
//! `scripts/generate_lufs_golden_vectors.py` and mirrored value-for-value
//! in `native/tests/lufs_golden_vectors.h`).
//!
//! Because this lane re-runs the very implementation the fixture was
//! derived from, the only admissible residual is cross-libm last-ulp
//! noise on the sine generators (~1e-9 LUFS on a ~1e5-sample integral)
//! — hence the tight 0.01 LUFS epsilon. The C++ lane
//! (`native/tests/test_lufs_rust_parity.cc`, CMake target
//! `lufs_parity_test_suite`) compares the same fixture against
//! `computeIntegratedLufs` with a documented 0.02 epsilon (f32
//! coefficient storage, f32 sample API).
//!
//! A failure here means one of exactly two things: the canonical
//! algorithm changed (regenerate the fixture via
//! `scripts/generate_lufs_golden_vectors.py` or
//! `cargo run -p streamify-audio --example lufs_golden_vectors` and
//! review the diff in the same PR), or the fixture and the
//! implementation have drifted apart — which is precisely the
//! cross-implementation rot C8 exists to catch.

mod lufs_golden_vectors_data;

use streamify_audio::lufs::LufsAnalyzer;

use lufs_golden_vectors_data::{
    AMP_M20_DBFS, AMP_M23_DBFS, AMP_M40_DBFS, AMP_NEAR_FS, FREQ_250_HZ, FREQ_440_HZ,
    FREQ_997_HZ, NOISE_MULTIPLIER, NOISE_SCALE, NOISE_SEED, SAMPLE_RATE_HZ,
    SILENCE_LEAD_FRAMES, TAU, VECTORS,
};

/// Rust-lane comparison bound (see the module docs for the derivation).
const EPSILON_LUFS: f64 = 0.01;

/// The canonical measurement: f32-quantized interleaved stereo in, gated
/// integrated LUFS out (the exact production entry point).
fn measure(interleaved: &[f32]) -> f64 {
    let mut analyzer = LufsAnalyzer::new().expect("canonical 48 kHz geometry");
    analyzer.process(interleaved);
    analyzer.integrated_lufs()
}

/// `mono` routes the signal to L with R silent — the documented mono
/// convention (a silent R adds nothing: both channel weights are 1.0).
fn sine_stereo(frames: usize, freq: f64, amp: f64, mono: bool) -> Vec<f32> {
    let mut out = Vec::with_capacity(frames * 2);
    for n in 0..frames {
        let x = (amp * (TAU * freq * n as f64 / SAMPLE_RATE_HZ as f64).sin()) as f32;
        out.push(x);
        out.push(if mono { 0.0 } else { x });
    }
    out
}

fn silence_then_sine_stereo(
    silence_frames: usize,
    tone_frames: usize,
    freq: f64,
    amp: f64,
) -> Vec<f32> {
    let mut out = Vec::with_capacity((silence_frames + tone_frames) * 2);
    for _ in 0..silence_frames {
        out.push(0.0);
        out.push(0.0);
    }
    for n in 0..tone_frames {
        let x = (amp * (TAU * freq * n as f64 / SAMPLE_RATE_HZ as f64).sin()) as f32;
        out.push(x);
        out.push(x);
    }
    out
}

/// ONE u64 xorshift64* stream with L/R consuming alternate steps — pure
/// integer math, bit-identical to the Python and C++ generators.
fn xorshift_noise_stereo(frames: usize) -> Vec<f32> {
    let mut s = NOISE_SEED;
    let mut next = || {
        s ^= s >> 12;
        s ^= s << 25;
        s ^= s >> 27;
        (s.wrapping_mul(NOISE_MULTIPLIER) as f64 / NOISE_SCALE - 1.0) as f32
    };
    let mut out = Vec::with_capacity(frames * 2);
    for _ in 0..frames {
        out.push(next());
        out.push(next());
    }
    out
}

/// Regenerate the fixture's signal by recipe key. Panics on an unknown
/// key — the fixture and this test are regenerated together, so a key
/// mismatch is a generator bug, not a runtime condition.
fn regenerate(name: &str) -> Vec<f32> {
    match name {
        "sine_997Hz_m23dBFS_mono_3s" => {
            sine_stereo(144_000, FREQ_997_HZ, AMP_M23_DBFS, true)
        }
        "sine_997Hz_m23dBFS_stereo_3s" => {
            sine_stereo(144_000, FREQ_997_HZ, AMP_M23_DBFS, false)
        }
        "sine_440Hz_0dBFS_stereo_2s" => {
            sine_stereo(96_000, FREQ_440_HZ, AMP_NEAR_FS, false)
        }
        "xorshift_noise_stereo_5s" => xorshift_noise_stereo(240_000),
        "silence_1s_then_sine_m20dBFS_stereo_2s" => silence_then_sine_stereo(
            SILENCE_LEAD_FRAMES,
            96_000,
            FREQ_440_HZ,
            AMP_M20_DBFS,
        ),
        "sine_250Hz_m40dBFS_stereo_3s" => {
            sine_stereo(144_000, FREQ_250_HZ, AMP_M40_DBFS, false)
        }
        other => panic!("unknown golden vector recipe key: {other}"),
    }
}

#[test]
fn canonical_analyzer_matches_the_shared_golden_fixture() {
    assert!(
        !VECTORS.is_empty(),
        "the golden fixture must carry at least one vector"
    );
    for &(name, channels, sample_count, expected) in VECTORS {
        let interleaved = regenerate(name);
        // Frame-count sanity: the recipe and the fixture must agree on
        // the signal geometry before any loudness comparison.
        assert_eq!(
            interleaved.len() / 2,
            sample_count,
            "{name}: frame count mismatch between recipe and fixture"
        );
        assert!(
            channels == 1 || channels == 2,
            "{name}: fixture channels must be 1 or 2"
        );

        let measured = measure(&interleaved);
        let delta = (measured - expected).abs();
        assert!(
            delta <= EPSILON_LUFS,
            "{name}: canonical analyzer drifted from the shared fixture: \
             measured {measured:.9} LUFS, fixture {expected:.9} LUFS, \
             delta {delta:.3e} > epsilon {EPSILON_LUFS}. Either the \
             canonical algorithm changed (regenerate the fixture and \
             review the diff) or the fixture has drifted — the exact rot \
             AHEAD C8 exists to catch."
        );
    }
}

#[test]
fn fixture_is_self_consistent_with_the_generator_parameters() {
    // Cheap structural pin: every vector's geometry is one the generator
    // actually emits (guards against hand-editing the fixture table).
    let known: Vec<&str> = VECTORS.iter().map(|(n, ..)| *n).collect();
    for expected_name in [
        "sine_997Hz_m23dBFS_mono_3s",
        "sine_997Hz_m23dBFS_stereo_3s",
        "sine_440Hz_0dBFS_stereo_2s",
        "xorshift_noise_stereo_5s",
        "silence_1s_then_sine_m20dBFS_stereo_2s",
        "sine_250Hz_m40dBFS_stereo_3s",
    ] {
        assert!(
            known.contains(&expected_name),
            "fixture is missing the '{expected_name}' vector — regenerate it"
        );
    }
}
